#cw-playtable{--cw-world-min:140px;--cw-field-min:110px;--cw-hand-min:182px;--cw-footer-height:32px;--cw-window:light-dark(#f7f8f4e0,#202820e6);--cw-paper:light-dark(#f7f8f4,#202820);--cw-ink:light-dark(#263c32,#f0f3ea);--cw-line:light-dark(#acbdad,#697767);--cw-soft:light-dark(#e9eee4,#303d2e);--cw-selected:light-dark(#345747,#c2d8ba);--cw-selected-ink:light-dark(#fff,#20311e);--cw-danger:light-dark(#943c25,#ffc5a8);--cw-alert:light-dark(#f9e9d9,#483126);position:relative;isolation:isolate;box-sizing:border-box;width:100%;max-width:100%;min-width:0;margin-inline:auto;color:var(--cw-ink);background:var(--cw-paper);border:1px solid var(--cw-line);border-radius:10px;padding:10px;font:14px/1.4 system-ui,sans-serif;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(var(--cw-world-min),1.2fr) minmax(var(--cw-field-min),.9fr) minmax(var(--cw-hand-min),1.2fr) var(--cw-footer-height);gap:6px;aspect-ratio:16/9;height:auto;min-height:calc(var(--cw-world-min) + var(--cw-field-min) + var(--cw-hand-min) + var(--cw-footer-height) + 40px);color-scheme:light dark;overflow-wrap:anywhere}
#cw-playtable *{box-sizing:border-box;min-width:0}#cw-playtable strong{font-weight:500}
#cw-playtable button,#cw-playtable select{font:inherit;color:var(--cw-ink);background:var(--cw-paper);border:1px solid var(--cw-line);border-radius:6px;padding:5px 8px;min-height:32px;max-width:100%;cursor:pointer}
#cw-playtable button:disabled{opacity:.5;cursor:default}#cw-playtable button[aria-pressed="true"]{box-shadow:inset 0 0 0 2px var(--cw-selected)}
#cw-playtable .cw-primary{background:var(--cw-selected);color:var(--cw-selected-ink);border-color:var(--cw-selected)}
#cw-playtable>.cw-world{grid-area:1/1}#cw-playtable>.cw-board{grid-area:2/1}#cw-playtable>.cw-hand-region{grid-area:3/1}#cw-playtable>.cw-bottom{grid-area:4/1}
#cw-playtable>.cw-region,#cw-playtable>.cw-bottom{position:relative;z-index:1}
#cw-playtable #cw-scene{position:absolute;inset:0;z-index:0;overflow:hidden;border-radius:9px;pointer-events:none}
#cw-playtable #cw-scene-base,#cw-playtable #cw-scene-environment,#cw-playtable .cw-environment-layer{position:absolute;inset:0;pointer-events:none}
#cw-playtable #cw-scene-base{background:linear-gradient(180deg,light-dark(#b7cfca,#3c5554) 0 7%,light-dark(#8ca791,#344e3e) 13%,light-dark(#88956b,#3d4d33) 20%,light-dark(#acaa84,#606346) 50%,light-dark(#74805a,#34452e) 100%)}
#cw-playtable #cw-scene-base:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 78% 12% at 50% 10%,light-dark(#e5ebcfb0,#a7bca128),transparent 75%),radial-gradient(ellipse 19% 34% at 0 15%,light-dark(#36553eef,#18352be8),transparent 85%),radial-gradient(ellipse 17% 32% at 100% 16%,light-dark(#3e5c3eeb,#1f392aea),transparent 85%),radial-gradient(ellipse 29% 35% at 0 96%,light-dark(#355335,#1d3426),transparent 85%),radial-gradient(ellipse 28% 32% at 100% 98%,light-dark(#3a5635,#1e3424),transparent 85%)}
#cw-playtable #cw-scene-base:after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse 70% 14% at 50% 24%,light-dark(#d2c8a0db,#7e806098) 0 48%,transparent 90%),radial-gradient(ellipse 82% 38% at 50% 60%,light-dark(#c5b893aa,#77745375),transparent 85%),linear-gradient(180deg,transparent 15%,light-dark(#ebe0b829,#bdb68b10) 31%,transparent 36%);opacity:.85}
#cw-playtable #cw-scene[data-terrain="followup"] #cw-scene-base{background:linear-gradient(180deg,light-dark(#c8d7cb,#4d635b) 0 7%,light-dark(#a1b293,#48583c) 13%,light-dark(#a4ae7c,#4c583a) 20%,light-dark(#c3bb8d,#74714b) 50%,light-dark(#829466,#405132) 100%)}
#cw-playtable #cw-scene-base[data-illustrated="true"]:before,#cw-playtable #cw-scene-base[data-illustrated="true"]:after{display:none}
#cw-playtable .cw-environment-layer[data-environment="O"]{background:radial-gradient(ellipse at 8% 44%,light-dark(#26342c70,#17211c80),transparent 48%)}
#cw-playtable .cw-environment-layer[data-environment="V0"]{background:repeating-linear-gradient(115deg,transparent 0 100px,light-dark(#eeeece16,#e0ddb008) 104px 122px)}
#cw-playtable .cw-environment-layer[data-environment="V1"]{background:radial-gradient(ellipse at 72% 22%,light-dark(#f5f3dc85,#c6ddb825),transparent 55%)}
#cw-playtable #cw-scene img{width:100%;height:100%;object-fit:cover}
#cw-playtable .cw-region{padding:4px;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr);gap:4px;min-height:0}
#cw-playtable .cw-heading{grid-area:1/1;display:flex;align-items:center;gap:8px;overflow:hidden;font-size:12px;white-space:nowrap}
