#cw-playtable .cw-heading>span:empty{display:none}#cw-playtable .cw-heading>span:first-child{flex-shrink:0}#cw-playtable .cw-heading>span:last-child:not(:first-child){margin-left:auto}
#cw-playtable .cw-scroll{grid-area:2/1/3/3;display:flex;gap:10px;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin;scrollbar-color:var(--cw-line) transparent;overscroll-behavior-x:contain;padding:2px 1px 5px}
#cw-playtable #cw-actors{padding-top:2px}
#cw-playtable .cw-scroll>*{flex:0 0 208px}#cw-playtable #cw-field>*{flex-basis:172px}#cw-playtable #cw-hand>*{flex-basis:184px}
