#cw-playtable .cw-scroll-help{grid-area:1/2;display:flex;align-items:center;gap:3px;font-size:12px;background:var(--cw-paper);border-radius:5px}
#cw-playtable .cw-scroll-help button{min-height:28px;padding:2px 7px;font-size:12px}#cw-playtable .cw-scroll-help span{text-align:center}#cw-playtable .cw-scroll-help[data-hidden="true"]{display:none}
#cw-playtable .cw-board{border:1px solid light-dark(#e2e6d785,#acbf9c45);border-radius:8px;background:light-dark(#e9eed81a,#192a171a)}
#cw-playtable .cw-board[data-drag="true"]{box-shadow:inset 0 0 0 3px var(--cw-selected)}#cw-playtable .cw-board[data-over="true"]{background:light-dark(#f9e9d977,#48312688)}
#cw-playtable .cw-actor,#cw-playtable .cw-slot,#cw-playtable .cw-select{position:relative;overflow:hidden;padding:0;display:flex;flex-direction:column;justify-content:flex-end;gap:0;font-size:12px;text-align:left;border-radius:6px}
#cw-playtable .cw-actor{border-color:transparent;background:transparent}#cw-playtable .cw-actor strong{font-size:14px}
#cw-playtable .cw-actor-head{display:flex;justify-content:space-between;align-items:center;gap:5px}
#cw-playtable progress{width:100%;height:5px;accent-color:var(--cw-selected)}
#cw-playtable .cw-slot{border:1px solid var(--cw-line);background:light-dark(#e8eed345,#20282050)}
#cw-playtable .cw-slot[data-linked="true"]{outline:2px solid var(--cw-selected);outline-offset:-2px}#cw-playtable .cw-slot[data-changed="true"]{border-color:var(--cw-danger)}
#cw-playtable .cw-attr{display:inline-block;border:1px solid currentColor;border-radius:4px;padding:0 4px;margin-right:5px}
#cw-playtable .cw-hand-region{grid-template-rows:auto minmax(0,1fr) 40px}
#cw-playtable .cw-hand-card{display:grid;grid-template-rows:minmax(0,1fr);border:1px solid var(--cw-line);border-radius:7px;background:var(--cw-paper)}
#cw-playtable .cw-hand-card[data-selected="true"]{border-color:var(--cw-selected);box-shadow:0 0 0 2px var(--cw-selected)}
#cw-playtable .cw-select{border:0;touch-action:pinch-zoom;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;cursor:grab}#cw-playtable .cw-select strong{font-size:14px}
#cw-playtable[data-card-drag="false"] .cw-select{touch-action:pan-x pan-y pinch-zoom;cursor:pointer}#cw-playtable .cw-hand-card[data-dragging="true"]{opacity:.6}
#cw-playtable .cw-illustration{position:absolute;inset:0;display:flex;align-items:flex-start;justify-content:center;background:linear-gradient(150deg,light-dark(#dfe4d3,#35452f),light-dark(#95b2ab,#2e4247));padding-top:8px;pointer-events:none}
#cw-playtable .cw-illustration[data-art-kind="actors"]{background:radial-gradient(ellipse at 50% 57%,light-dark(#7e978bd9,#809382c9) 0 30%,transparent 32%);padding-top:10px}
#cw-playtable .cw-illustration img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
#cw-playtable .cw-face-caption{position:relative;z-index:1;display:flex;flex-direction:column;gap:2px;width:100%;padding:5px 7px;background:var(--cw-paper);color:var(--cw-ink)}
#cw-playtable .cw-menu{grid-area:1/2;display:flex;align-items:center;gap:4px;overflow-x:auto;scrollbar-width:thin;overscroll-behavior-x:contain}#cw-playtable .cw-menu button{flex-shrink:0;font-size:12px;white-space:nowrap;min-height:28px;padding:3px 6px}
#cw-playtable .cw-event-region{position:absolute;z-index:3;right:12px;bottom:calc(var(--cw-footer-height) + 16px);width:min(440px,calc(100% - 24px));height:156px;pointer-events:none}
#cw-playtable #cw-event-feed{position:relative;width:100%;height:100%;list-style:none;margin:0;padding:0;pointer-events:none}
#cw-playtable .cw-live-event{position:absolute;left:0;display:flex;gap:8px;width:max-content;max-width:100%;height:24px;font-size:12px;line-height:20px;white-space:nowrap;padding:2px 8px;border-radius:4px;background:var(--cw-window);color:var(--cw-ink);opacity:1;transition:bottom .18s ease-out,opacity 1.5s ease-out}
#cw-playtable .cw-live-event[data-fading="true"]{opacity:0}
#cw-playtable .cw-live-event span{min-width:0;overflow:hidden;text-overflow:ellipsis}
#cw-playtable .cw-live-event time{flex-shrink:0;min-width:3ch;text-align:right;font-variant-numeric:tabular-nums;opacity:.7}
