#cw-playtable #cw-turn-order li+li:before{content:"›";color:var(--cw-ink);background:var(--cw-paper);border-radius:3px;padding:0 2px}
#cw-playtable [data-turn-actor]{display:flex;align-items:center;gap:4px;font-size:11px;padding:2px 5px;min-height:32px}
#cw-playtable [data-turn-actor][data-current="true"]{background:var(--cw-selected);color:var(--cw-selected-ink)}
#cw-playtable .cw-turn-face{display:grid;place-items:center;position:relative;width:24px;height:24px;overflow:hidden;border:1px solid currentColor;border-radius:50%;font-size:12px}
