#cw-playtable .cw-order-strip>button{padding:2px 4px;flex-shrink:0}
@media(pointer:coarse){#cw-playtable [data-turn-actor],#cw-playtable .cw-order-strip>button{min-width:44px;min-height:44px}}

#cw-playtable #cw-backdrop{pointer-events:none}
#cw-playtable #cw-window-state{font-size:11px;margin-left:auto;margin-right:10px}
#cw-playtable .cw-card-columns{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:24px}
