#cw-playtable .cw-drawer[data-window="field"],#cw-playtable .cw-drawer[data-window="actor"],#cw-playtable .cw-drawer[data-window="objective"],#cw-playtable .cw-drawer[data-window="order"]{width:min(420px,calc(100% - 24px))}

#cw-playtable #cw-relations{position:absolute;inset:0;width:100%;height:100%;z-index:2;overflow:hidden;pointer-events:none;color:var(--cw-selected)}
#cw-playtable #cw-relations *{pointer-events:none}
