#cw-playtable #cw-relation-arrow path{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#cw-playtable .cw-relation-marks rect{fill:none;stroke:currentColor;stroke-width:2;opacity:.3}
#cw-playtable #cw-relations[data-mode="place"] .cw-relation-lines path{stroke-dasharray:5 5}
#cw-playtable [data-field-card]{cursor:pointer}#cw-playtable [data-field-card][aria-expanded="true"]{outline:2px solid var(--cw-selected);outline-offset:-2px}

/* Keep the composition centered in the available window, with no intrinsic-width expansion. */
#cw-playtable>.cw-region,#cw-playtable>.cw-bottom{max-width:100%;width:100%;min-width:0}
#cw-playtable .cw-icon{width:18px;height:18px;vertical-align:middle;flex-shrink:0}
#cw-playtable .cw-actor .cw-illustration{position:absolute;inset:0;min-height:0;width:100%;height:100%;align-items:center;padding:0 0 12px;background:radial-gradient(ellipse at 50% 90%,light-dark(#40564140,#a5b89725),transparent 62%)}
#cw-playtable .cw-actor .cw-illustration .cw-icon{width:100%;height:100%;max-width:200px;filter:drop-shadow(0 2px 1px light-dark(#dfe7c7,#243a29));color:light-dark(#294737,#d9e4be);stroke-width:1.6}
#cw-playtable .cw-actor .cw-face-caption{flex-shrink:0;background:var(--cw-window);padding:3px 6px;gap:0}
#cw-playtable .cw-actor-head strong{font-size:12px}
#cw-playtable .cw-illustration[data-art-kind="cards"]>.cw-icon{width:40px;height:40px;color:light-dark(#395b4c,#d0dcc0)}
#cw-playtable .cw-bottom>#cw-withdraw{grid-area:1/3;white-space:nowrap;min-height:28px;padding:3px 8px;font-size:12px}
#cw-playtable button.cw-withdraw{color:var(--cw-danger);background:var(--cw-alert);border-color:var(--cw-danger)}
#cw-playtable #cw-deck-summary{margin:8px 0}
#cw-playtable #cw-deck-summary>span{display:inline-flex;align-items:center;gap:4px;margin-right:8px}
#cw-playtable .cw-catalogue{display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:10px;margin-top:12px}
#cw-playtable .cw-deck-card{position:relative;display:flex;flex-direction:column;justify-content:flex-end;overflow:hidden;height:126px;padding:0;font-size:12px;text-align:left}
#cw-playtable .cw-deck-card .cw-face-caption{padding:5px;gap:3px}
#cw-playtable .cw-deck-card .cw-attr{align-self:flex-start}
#cw-playtable .cw-deck-card[data-empty="true"]{opacity:.55}
#cw-playtable .cw-deck-number{position:absolute;top:5px;right:5px;z-index:1;min-width:24px;text-align:center;border-radius:4px;background:var(--cw-paper);padding:1px 4px}
#cw-playtable .cw-catalogue-peek{z-index:9;width:min(320px,calc(100% - 24px));padding:10px}
#cw-playtable .cw-catalogue-peek header{gap:6px}
#cw-playtable #cw-catalogue-name{margin-right:auto}
#cw-playtable #cw-deck-title{margin-top:0}
#cw-playtable #cw-reenter{margin-top:16px}
@media(pointer:coarse){#cw-playtable .cw-bottom>#cw-withdraw{min-height:44px}}

#cw-playtable .cw-facts{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:7px 14px;margin:8px 0;font-size:12px}
#cw-playtable .cw-facts dt,#cw-playtable .cw-facts dd{margin:0}
#cw-playtable .cw-facts dt{color:var(--cw-ink);opacity:.8}
#cw-playtable #cw-prediction>.cw-impact{margin-top:8px}
#cw-playtable #cw-calculation{margin-top:14px}

#cw-playtable .cw-field-name{display:flex;align-items:center;gap:3px;min-width:0}
#cw-playtable .cw-field-name>.cw-attr,#cw-playtable .cw-field-name>span:last-child{flex-shrink:0}
#cw-playtable .cw-field-name>strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Same structural CSS as UI-R-002 v0.15, with the M1 public-data adapter. */
.cw-explore{container-type:inline-size;--cw-window:var(--cw-paper)}
.cw-explore #cw-scene-base{background:linear-gradient(180deg,light-dark(#88a6ae,#23343e),light-dark(#d2d9d0,#384847))}
.cw-explore #cw-scene-base:before,.cw-explore #cw-scene-base:after{display:none}
.cw-explore .cw-illustration>span{font-size:2em}
.cw-explore .cw-ledger{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 12px}
.cw-explore .cw-ledger dt,.cw-explore .cw-ledger dd{margin:0;overflow-wrap:anywhere}
.cw-explore .cw-ledger dd{font-variant-numeric:tabular-nums}
.cw-explore #cw-action-anchor{width:min(240px,100%)}
.cw-explore #cw-window-state{padding:3px 7px;min-width:32px}
.cw-explore .cw-drawer{background:var(--cw-paper)}
.cw-explore .cw-drawer-body{overscroll-behavior:contain}
.cw-explore #cw-relations{position:absolute;inset:0;width:100%;height:100%;z-index:2;pointer-events:none;opacity:.5;color:var(--cw-selected)}
@container(max-width:600px){
 .cw-explore .cw-bottom{grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto;gap:4px}
 .cw-explore .cw-footer-state{grid-area:1/1}
 .cw-explore .cw-menu{grid-area:2/1/3/3}
 .cw-explore [data-x="withdraw"]{grid-area:1/2}
 .cw-explore .cw-self{font-size:12px}
}
@media(max-width:600px){.cw-explore{--cw-footer-height:76px}}
@media(pointer:coarse){.cw-explore{--cw-footer-height:96px}.cw-explore #cw-window-state{min-width:44px;min-height:44px}}

/* Fit the available game rectangle; do not retain the fixed minima of the reference. */
.cw-explore{min-height:0;grid-template-rows:minmax(0,.95fr) minmax(0,.75fr) minmax(0,1.25fr) var(--cw-footer-height);gap:4px;padding:6px;overflow:hidden}
.cw-explore .cw-region{min-height:0;padding:2px;gap:2px}
.cw-explore .cw-heading{min-height:0}
.cw-explore .cw-scroll{min-height:0;gap:6px;padding:1px 1px 3px}
.cw-explore .cw-actor-item{display:grid;grid-template-columns:minmax(0,1fr) 36px;gap:2px;min-height:0}
.cw-explore .cw-actor-item .cw-actor{width:100%;height:100%;min-height:0}
.cw-explore .cw-actor-info{padding:0;align-self:end;min-width:36px;min-height:36px;display:grid;place-items:center}
.cw-explore .cw-stat-line{display:flex;flex-wrap:wrap;gap:5px 10px;align-items:center}
.cw-explore .cw-stat{display:inline-flex;gap:3px;align-items:center;white-space:nowrap}
.cw-explore .cw-stat b{font-weight:500;font-variant-numeric:tabular-nums}
.cw-explore .cw-stat i,.cw-explore .cw-stat svg{font-style:normal;width:16px;height:16px;flex:none}
.cw-explore .cw-menu button{display:inline-flex;align-items:center;gap:4px}
.cw-explore .cw-menu i,.cw-explore .cw-menu svg{width:16px;height:16px;flex:none}
.cw-explore .cw-bottom{grid-template-columns:auto minmax(0,1fr) auto;grid-template-rows:minmax(0,1fr);gap:5px;padding:0 3px}
.cw-explore .cw-footer-state{grid-area:1/1;display:flex;align-items:center;gap:5px}
.cw-explore .cw-menu{grid-area:1/2;min-width:0;height:100%;overflow-y:hidden}
.cw-explore [data-x="withdraw"]{grid-area:1/3;min-height:32px;padding:4px 6px;font-size:12px}
.cw-explore #cw-action-anchor{width:min(240px,100%)}
.cw-explore .cw-drawer,.cw-explore .cw-drawer[data-window="card"]{padding:6px;grid-template-rows:auto minmax(0,1fr);min-height:0;overflow:hidden;background:var(--cw-paper)}
.cw-explore .cw-drawer>header{min-height:36px;gap:6px}
.cw-explore .cw-drawer>header strong{margin-right:auto;font-size:13px}
.cw-explore .cw-drawer>header button{flex:none;padding:2px 6px}
.cw-explore .cw-drawer-body{min-height:0;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin}
.cw-explore[data-compact="true"]{grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:minmax(0,.9fr) minmax(0,1fr) var(--cw-footer-height);padding:4px;gap:3px}
.cw-explore[data-compact="true"]>.cw-world{grid-area:1/1}
.cw-explore[data-compact="true"]>.cw-board{grid-area:1/2}
.cw-explore[data-compact="true"]>.cw-hand-region{grid-area:2/1/3/3;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr)}
.cw-explore[data-compact="true"]>.cw-hand-region>.cw-heading{position:absolute;z-index:2;top:0;left:0}
.cw-explore[data-compact="true"]>.cw-hand-region>.cw-scroll-help{display:none}
.cw-explore[data-compact="true"] #cw-hand{grid-area:1/1}
.cw-explore[data-compact="true"] #cw-action-track{display:none}
.cw-explore[data-compact="true"][data-selection="true"]>.cw-hand-region{grid-template-columns:minmax(0,1fr) 146px;gap:4px}
.cw-explore[data-compact="true"][data-selection="true"] #cw-action-track{display:block;grid-area:1/2;align-self:stretch;min-height:0}
.cw-explore[data-compact="true"] #cw-action-anchor{position:static;width:100%;height:100%;align-items:center;gap:3px}
.cw-explore[data-compact="true"] #cw-action-anchor:before{display:none}
.cw-explore[data-compact="true"] #cw-action-anchor button{min-width:0;padding:3px;font-size:12px;height:auto;max-height:100%}
.cw-explore[data-compact="true"]>.cw-bottom{grid-area:3/1/4/3}
.cw-explore[data-compact="true"] .cw-menu button>span{display:none}
.cw-explore[data-compact="true"] .cw-menu button{min-width:36px;justify-content:center}
.cw-explore[data-dense="true"] .cw-world,.cw-explore[data-dense="true"] .cw-board{grid-template-rows:minmax(0,1fr);grid-template-columns:minmax(0,1fr);padding:0;gap:0}
.cw-explore[data-dense="true"] .cw-world>.cw-heading,.cw-explore[data-dense="true"] .cw-board>.cw-heading,.cw-explore[data-dense="true"] .cw-scroll-help{display:none}
.cw-explore[data-dense="true"] .cw-world>.cw-scroll,.cw-explore[data-dense="true"] .cw-board>.cw-scroll{grid-area:1/1}
.cw-explore[data-dense="true"] .cw-scroll>*{flex-basis:144px}
.cw-explore[data-dense="true"] #cw-field>*{flex-basis:114px}
.cw-explore[data-dense="true"] #cw-hand>*{flex-basis:126px}
.cw-explore[data-dense="true"] .cw-illustration{display:none}
.cw-explore[data-dense="true"] .cw-face-caption{padding:2px 4px;gap:0;font-size:11px;height:100%;justify-content:center}
.cw-explore[data-dense="true"] .cw-face-caption strong{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cw-explore[data-dense="true"] .cw-life{font-size:11px}
.cw-explore[data-dense="true"] .cw-actor progress{display:none}
.cw-explore[data-dense="true"] #cw-hand-count{display:none}
.cw-explore[data-dense="true"] .cw-footer-state{max-width:60px}
@media(pointer:coarse){
 .cw-explore .cw-actor-item{grid-template-columns:minmax(0,1fr) 44px}
 .cw-explore .cw-actor-info,.cw-explore .cw-menu button,.cw-explore [data-x="withdraw"]{min-width:44px;min-height:44px}
 .cw-explore .cw-drawer>header{min-height:44px}
 .cw-explore[data-compact="true"] .cw-menu button{min-width:44px}
}

/* Actor values are part of the actor face, including zero, not drawer content.
 * Many actors stay in one horizontal strip; only one target-detail control. */
.cw-explore .cw-actor-item{grid-template-columns:minmax(0,1fr)}
.cw-explore .cw-actor{touch-action:pan-x;user-select:none;-webkit-user-select:none}
.cw-explore .cw-actor-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;width:100%;font-size:12px;line-height:16px}
.cw-explore .cw-actor-stats .cw-stat{gap:2px}
.cw-explore .cw-actor-stats svg,.cw-explore .cw-actor-stats i{width:14px;height:14px}
.cw-explore .cw-actor .cw-face-caption{padding:2px 4px;gap:0;line-height:16px}
.cw-explore .cw-actor .cw-face-caption>strong{line-height:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cw-explore .cw-actor-hp{font-variant-numeric:tabular-nums;white-space:nowrap}
.cw-explore .cw-self{display:grid;grid-template-rows:16px 16px;gap:0;min-width:140px;width:140px;font-size:12px;line-height:16px}
.cw-explore .cw-self-hp{display:flex;gap:8px;align-items:center}
.cw-explore .cw-footer-state{overflow:visible;max-width:none}
.cw-explore .cw-menu{scrollbar-width:none}
.cw-explore[data-compact="true"] #cw-hand-count{display:none}
.cw-explore[data-dense="true"] .cw-footer-state{max-width:none}
.cw-explore[data-dense="true"] .cw-actor .cw-face-caption{padding:0 4px;height:auto;min-height:48px;justify-content:center}
.cw-explore[data-dense="true"] .cw-actor .cw-face-caption>strong{font-size:12px;line-height:16px}
.cw-explore[data-dense="true"] .cw-world .cw-scroll{padding-bottom:0;scrollbar-width:none}
.cw-explore[data-dense="true"]{grid-template-columns:minmax(160px,1fr) minmax(0,1fr)}
.cw-explore[data-dense="true"] #cw-actors>.cw-actor-item{flex-basis:152px}
.cw-explore[data-dense="true"] .cw-actor-stats{font-size:11px;gap:2px}
.cw-explore[data-dense="true"] .cw-actor-stats .cw-stat{gap:1px}
.cw-explore[data-dense="true"] .cw-actor-stats svg,.cw-explore[data-dense="true"] .cw-actor-stats i{width:12px;height:12px}

/* v0.7: current actor state and the selected action share the same surface.
 * The only scrolling outside a drawer is within the existing card strips. */
.cw-explore .cw-vitals{display:flex;justify-content:space-between;align-items:center;gap:4px;font-size:12px;line-height:16px;font-variant-numeric:tabular-nums}
.cw-explore .cw-vitals .cw-stat{gap:2px}
.cw-explore .cw-vitals svg,.cw-explore .cw-vitals i{width:12px;height:12px}
.cw-explore .cw-vital-bars{display:grid;grid-template-rows:3px 3px;gap:1px;width:100%;margin:1px 0}
.cw-explore .cw-vital-bars progress{display:block;appearance:none;border:0;border-radius:0;padding:0;margin:0;width:100%;height:3px;background:var(--cw-soft);color:var(--cw-selected)}
.cw-explore .cw-vital-bars progress::-webkit-progress-bar{background:var(--cw-soft)}
.cw-explore .cw-vital-bars progress::-webkit-progress-value{background:var(--cw-selected)}
.cw-explore .cw-vital-bars progress::-moz-progress-bar{background:var(--cw-selected)}
.cw-explore .cw-vital-bars progress+progress{opacity:.6}
.cw-explore .cw-actor-stats{display:flex;justify-content:space-between;gap:3px}
.cw-explore .cw-delta{font-size:11px;font-weight:400;line-height:14px;color:var(--cw-selected);margin-left:1px}
.cw-explore .cw-target-mark{display:inline-flex;vertical-align:middle;margin-right:3px}
.cw-explore .cw-target-mark svg,.cw-explore .cw-target-mark i{width:12px;height:12px}
.cw-explore .cw-actor[aria-pressed="true"]{outline:2px solid var(--cw-selected);outline-offset:-2px}
.cw-explore .cw-actor[aria-pressed="true"] .cw-face-caption{background:var(--cw-soft)}
.cw-explore .cw-self{grid-template-rows:16px 9px 16px;min-width:156px;width:156px;gap:0}
.cw-explore .cw-bottom{grid-template-columns:auto 1fr auto;gap:3px;padding:0}
.cw-explore .cw-menu{justify-content:flex-end;overflow:visible;gap:2px}
.cw-explore .cw-menu button{min-width:44px;height:44px;min-height:44px;padding:0 7px;justify-content:center}
.cw-explore [data-x="withdraw"]{min-width:44px;min-height:44px;height:44px;padding:0 4px}
.cw-explore #cw-action-anchor{width:max-content;max-width:100%;gap:4px}
.cw-explore #cw-action-anchor button,.cw-explore #cw-use{flex:0 0 auto;min-width:44px;min-height:44px;padding:0 8px;white-space:nowrap}
.cw-explore[data-compact="true"][data-selection="true"]>.cw-hand-region{grid-template-columns:minmax(0,1fr) max-content}
.cw-explore[data-compact="true"] #cw-action-anchor{width:max-content;height:100%}
.cw-explore[data-compact="true"] #cw-action-anchor button{min-width:44px;min-height:44px;height:44px;padding:0 6px}
.cw-explore .cw-field-forecast{background:var(--cw-soft);border-style:dashed}
.cw-explore .cw-field-change{font-size:11px;line-height:14px}
.cw-explore .cw-ledger{grid-template-columns:max-content minmax(0,max-content);justify-content:start;gap:6px 10px}
.cw-explore .cw-ledger dt{display:flex;align-items:center;gap:3px;white-space:nowrap}
.cw-explore .cw-ledger dt i,.cw-explore .cw-ledger dt svg{width:14px;height:14px}
.cw-explore .cw-ledger dd{overflow-wrap:break-word}
.cw-explore .cw-ledger small{font-size:11px}
.cw-explore .cw-drawer-body h3{font-size:12px;font-weight:500;margin:14px 0 6px}
.cw-explore .cw-reservations{list-style:none;padding:0;margin:0;display:grid;gap:8px}
.cw-explore .cw-reservations>li{display:flex;justify-content:space-between;gap:16px}
.cw-explore .cw-reservations b{font-weight:500;font-variant-numeric:tabular-nums}
.cw-explore .cw-more{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.cw-explore .cw-more button{display:flex;align-items:center;gap:6px;min-height:44px;white-space:nowrap}
.cw-explore .cw-more svg,.cw-explore .cw-more i{width:16px;height:16px;flex:none}
.cw-explore[data-dense="true"]{grid-template-columns:minmax(174px,1fr) minmax(0,1fr);grid-template-rows:64px minmax(0,1fr) 44px}
.cw-explore[data-dense="true"] #cw-actors>.cw-actor-item{flex-basis:166px}
.cw-explore[data-dense="true"] .cw-actor .cw-face-caption{min-height:60px;padding:0 4px}
.cw-explore[data-dense="true"] .cw-vitals{font-size:11px}
.cw-explore[data-dense="true"] .cw-actor progress{display:block}
.cw-explore[data-dense="true"] .cw-menu button{width:44px;padding:0}
.cw-explore[data-dense="true"] #cw-hand{padding-bottom:0}

/* v0.8: reserve the entire numeric caption, including inline forecast deltas. */
.cw-explore .cw-vitals,.cw-explore .cw-actor-stats{min-width:0;width:100%}
.cw-explore .cw-vitals .cw-stat,.cw-explore .cw-actor-stats .cw-stat{flex:none}
.cw-explore .cw-actor .cw-face-caption{flex:0 0 auto;min-height:61px}
.cw-explore .cw-actor-item{min-height:61px}
.cw-explore[data-dense="true"] #cw-actors{padding:0 1px}
.cw-explore .cw-ledger{grid-template-columns:minmax(0,max-content) minmax(0,1fr)}
.cw-explore .cw-ledger dt{white-space:normal}
.cw-explore .cw-properties ul{margin:0;padding-left:1.2em;display:grid;gap:6px}
.cw-explore .cw-prose-line{display:block;white-space:normal;overflow-wrap:break-word;text-wrap:wrap}
.cw-explore #cw-window-state{display:grid;place-items:center;min-width:44px;min-height:44px;padding:0}
.cw-explore #cw-window-state i,.cw-explore #cw-window-state svg{width:16px;height:16px}
.cw-explore #cw-window-state[aria-pressed="true"]{background:var(--cw-selected);color:var(--cw-selected-ink)}
.cw-explore .cw-drawer{container-type:inline-size}
.cw-explore .cw-drawer>header button{min-width:44px;min-height:44px;height:44px;padding:0}
.cw-explore .cw-drawer>header i,.cw-explore .cw-drawer>header svg{width:16px;height:16px}
.cw-explore [data-x="parent-pin"][aria-pressed="true"]{background:var(--cw-selected);color:var(--cw-selected-ink)}
@container(max-width:260px){
 .cw-explore .cw-drawer>header{flex-wrap:wrap;gap:0}
 .cw-explore .cw-drawer>header strong{flex-basis:100%;order:-1;font-size:13px;line-height:18px;max-height:36px;overflow:auto}
 .cw-explore .cw-drawer>header button:last-child{margin-left:auto}
 .cw-explore .cw-more{grid-template-columns:minmax(0,1fr)}
}

#crossweave-journey{container-type:inline-size;color-scheme:light dark;color:light-dark(#243d35,#e6ece3);font:14px/1.55 system-ui,-apple-system,"Noto Sans JP",sans-serif;max-width:100%;min-width:0}
#crossweave-journey *{box-sizing:border-box;min-width:0}
#crossweave-journey [hidden]{display:none!important}
#crossweave-journey button,#crossweave-journey textarea,#crossweave-journey input{font:inherit}
#crossweave-journey h1,#crossweave-journey h2,#crossweave-journey h3,#crossweave-journey p{margin:0}
#crossweave-journey h1{font:400 32px/1.3 Georgia,"Yu Mincho",serif;letter-spacing:.12em}
#crossweave-journey h2{font-size:17px;font-weight:500}
