#crossweave-journey .cj-header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:10px 18px;border-bottom:1px solid light-dark(#d3dbcf,#40524a)}
#crossweave-journey .cj-brand{font-family:Georgia,serif;font-size:20px;letter-spacing:.07em;display:flex;gap:12px;align-items:center}
#crossweave-journey .cj-brand>span{font:11px/1.5 system-ui,sans-serif;letter-spacing:.05em;color:light-dark(#607368,#acbbaf);border-left:1px solid light-dark(#b3c0b3,#52665b);padding-left:12px}
#crossweave-journey .cj-header nav{display:flex;gap:4px;flex-wrap:wrap}
