.cw-hold-label{position:absolute;top:34px;left:50%;transform:translateX(-50%);white-space:nowrap;font:500 12px/18px system-ui,sans-serif;padding:0 4px;border-radius:3px;background:var(--cw-hold-paper);color:var(--cw-hold-ink)}

